public static partial class ItalianQuotes
{
    public static class EugenioMontale
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://it.wikiquote.org/wiki/Eugenio_Montale", Text = "Codesto solo oggi possiamo dirti: ciò che non siamo, ciò che non vogliamo.", Author = "Eugenio Montale" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Eugenio_Montale", Text = "Da loro c'è sempre da imparare. Possiedono alcuni concetti fondamentali, quelli che contano. Purtroppo, pare che ne siano rimasti pochi.", Author = "Eugenio Montale" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Eugenio_Montale", Text = "Ho imparato una verità che pochi conoscono: che l'arte largisce le sue consolazioni soprattutto agli artisti falliti.", Author = "Eugenio Montale" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Eugenio_Montale", Text = "Il rapporto tra l'alfabetismo e l'analfabetismo è costante, ma al giorno d'oggi gli analfabeti sanno leggere.", Author = "Eugenio Montale" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Eugenio_Montale", Text = "Il vero genovese era \"stúndàiu\" (la parola non è sdrucciola e occorre un forte accento sulla prima u), e quindi poco sociale.", Author = "Eugenio Montale" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Eugenio_Montale", Text = "Io sono qui perché ho scritto poesie, un prodotto assolutamente inutile, ma quasi mai nocivo.", Author = "Eugenio Montale" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Eugenio_Montale", Text = "L'uomo coltiva la propria infelicità per avere il gusto di combatterla a piccole dosi.", Author = "Eugenio Montale" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Eugenio_Montale", Text = "L'uomo d'oggi ha ereditato un sistema nervoso che non sopporta le attuali condizioni di vita.", Author = "Eugenio Montale" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Eugenio_Montale", Text = "La più vera ragione è di chi tace.", Author = "Eugenio Montale" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Eugenio_Montale", Text = "Ma bisogna andare in Oriente per capire cos'è la religione.", Author = "Eugenio Montale" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Eugenio_Montale", Text = "Milano è un enorme conglomerato di eremiti.", Author = "Eugenio Montale" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Eugenio_Montale", Text = "Nei tempi più gloriosi dell'arte, gli artisti si esprimevano imitando i grandi artisti del passato, e imitando trovavano se stessi.", Author = "Eugenio Montale" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Eugenio_Montale", Text = "Ormai sono abituato a soffrire, e forse ne ho la necessità.", Author = "Eugenio Montale" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Eugenio_Montale", Text = "Quando il sesso era misterioso aveva un certo fascino che ora non ha più.", Author = "Eugenio Montale" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Eugenio_Montale", Text = "Sarò anche conservatore; ma che cosa c'è poi da conservare?", Author = "Eugenio Montale" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Eugenio_Montale", Text = "Sono rispettosissimo di tutte le religioni, ma la religione laica mi pare la più ridicola delle religioni.", Author = "Eugenio Montale" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Eugenio_Montale", Text = "Un misto di orgoglio, di timidezza, di diffidenza, una pratica quotidiana del mugugno, un certo complesso d'inferiorità bilanciato dal senso di una specifica superiorità nell'ordine dei valori morali.", Author = "Eugenio Montale" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Eugenio_Montale", Text = "L'istruzione obbligatoria, il suffragio universale e il voto alle donne (tutte cose, puramente, necessarie).", Author = "Eugenio Montale" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Eugenio_Montale", Text = "Accorgersi che si può decidere qualcosa, che in qualche misura esiste il \"libero arbitrio\".", Author = "Eugenio Montale" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Eugenio_Montale", Text = "Abolirei il cinema.", Author = "Eugenio Montale" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Eugenio_Montale", Text = "Andate a dire all'uomo della strada, all'uomo che non è stato all'università, che un uomo può essere un grande artista e, insieme, un uomo immorale e persino un criminale.", Author = "Eugenio Montale" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Eugenio_Montale", Text = "Alte tremano guglie di sambuchi e sovrastano al poggio cui domina una statua dell'Estate fatta camusa da lapidazioni.", Author = "Eugenio Montale" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Eugenio_Montale", Text = "Torna l'avvenimento del sole e le diffuse voci, i consueti strepiti non porta.", Author = "Eugenio Montale" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Eugenio_Montale", Text = "Spesso il male di vivere ho incontrato: era il rivo strozzato che gorgoglia, era l'incartocciarsi della foglia riarsa, era il cavallo stramazzato.", Author = "Eugenio Montale" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Eugenio_Montale", Text = "Ascoltami, i poeti laureati si muovono soltanto fra le piante dai nomi poco usati.", Author = "Eugenio Montale" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Eugenio_Montale", Text = "Riviere, bastano pochi stocchi d'erbaspada penduli da un ciglione sul delirio del mare.", Author = "Eugenio Montale" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Eugenio_Montale", Text = "Non chiederci la parola che squadri da ogni lato l'animo nostro informe, e a lettere di fuoco lo dichiari e risplenda come un croco perduto in mezzo a un polveroso prato.", Author = "Eugenio Montale" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Eugenio_Montale", Text = "Felicità raggiunta, si cammina per te sul fil di lama. Agli occhi sei barlume che vacilla, al piede, teso ghiaccio che s'incrina.", Author = "Eugenio Montale" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Eugenio_Montale", Text = "Godi se il vento ch'entra nel pomario vi rimena l'ondata della vita: qui dove affonda un morto viluppo di memorie, orto non era, ma reliquario.", Author = "Eugenio Montale" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Eugenio_Montale", Text = "Va', per te l'ho pregato, – ora la sete mi sarà lieve, meno acre la ruggine.", Author = "Eugenio Montale" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Eugenio_Montale", Text = "Ma in attendere è gioia più compita.", Author = "Eugenio Montale" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Eugenio_Montale", Text = "Sotto l'azzurro fitto del cielo qualche uccello di mare se ne va; né sosta mai: perché tutte le immagini portano scritto \"più in là\".", Author = "Eugenio Montale" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Eugenio_Montale", Text = "Voi, mie parole, tradite invano il morso secreto, il vento nel cuore soffia. La più vera ragione è di chi tace.", Author = "Eugenio Montale" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Eugenio_Montale", Text = "Upupa, ilare uccello calunniato dai poeti, che roti la tua cresta sopra l'aereo stollo del pollaio.", Author = "Eugenio Montale" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Eugenio_Montale", Text = "E ora che ne sarà del mio viaggio? Troppo accuratamente l'ho studiato senza saperne nulla.", Author = "Eugenio Montale" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Eugenio_Montale", Text = "Il genio purtroppo non parla per bocca sua. Il genio lascia qualche traccia di zampetta come la lepre sulla neve.", Author = "Eugenio Montale" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Eugenio_Montale", Text = "Le rime sono più noiose delle dame di San Vincenzo: battono alla porta e insistono.", Author = "Eugenio Montale" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Eugenio_Montale", Text = "Prima del viaggio si scrutano gli orari, le coincidenze, le soste, le pernottazioni e le prenotazioni.", Author = "Eugenio Montale" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Eugenio_Montale", Text = "Ho sceso, dandoti il braccio almeno un milione di scale e ora che non ci sei è il vuoto ad ogni gradino.", Author = "Eugenio Montale" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Eugenio_Montale", Text = "Il mio dura tuttora, né più mi occorrono le coincidenze, le prenotazioni, le trappole, gli scorni di chi crede che la realtà sia quella che si vede.", Author = "Eugenio Montale" },
        };
    }
